/** Returns true if the intent is past its TTL given the local clock (with skew tolerance). */
export function isExpired(intent: PaymentIntent, nowMs = Date.now(), skewMs = 60_000): boolean {
  return nowMs > intent.ts + intent.ttl + skewMs;
}
